function Card3D({ children, className, style, glowColor = "rgba(201,168,76,0.3)" }) {
  const ref = useRef(null);
  const [cardStyle, setCardStyle] = useState({});

  const handleMouseMove = (e) => {
    const rect = ref.current.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width - 0.5;
    const y = (e.clientY - rect.top) / rect.height - 0.5;
    const lightX = ((e.clientX - rect.left) / rect.width) * 100;
    const lightY = ((e.clientY - rect.top) / rect.height) * 100;
    setCardStyle({
      transform: `perspective(600px) rotateY(${x * 20}deg) rotateX(${-y * 20}deg) translateZ(30px) scale3d(1.05,1.05,1.05)`,
      boxShadow: `0 25px 60px rgba(0,0,0,0.5), 0 0 30px ${glowColor}, inset 0 0 0 1px rgba(255,255,255,0.08)`,
      "--light-x": `${lightX}%`,
      "--light-y": `${lightY}%`,
    });
  };

  const handleMouseLeave = () => {
    setCardStyle({
      transform: "perspective(600px) rotateY(0deg) rotateX(0deg) translateZ(0px) scale3d(1,1,1)",
      boxShadow: "0 4px 20px rgba(0,0,0,0.3)",
      "--light-x": "50%",
      "--light-y": "50%",
    });
  };

  const handleTouchStart = () => {
    setCardStyle({
      transform: "perspective(600px) rotateY(0deg) rotateX(-3deg) translateZ(20px) scale3d(1.04,1.04,1.04)",
      boxShadow: `0 20px 50px rgba(0,0,0,0.5), 0 0 25px ${glowColor}`,
    });
  };

  const handleTouchEnd = () => handleMouseLeave();

  return (
    <div
      ref={ref}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      className={className}
      style={{
        ...style,
        ...cardStyle,
        transition: "all 0.4s cubic-bezier(.03,.98,.52,.99)",
        transformStyle: "preserve-3d",
        willChange: "transform, box-shadow",
      }}
    >
      {/* Light reflection overlay */}
      <div style={{
        position: "absolute", inset: 0, pointerEvents: "none", zIndex: 10,
        background: `radial-gradient(circle at var(--light-x, 50%) var(--light-y, 50%), rgba(255,255,255,0.08) 0%, transparent 60%)`,
        transition: "background 0.3s",
      }} />
      {children}
    </div>
  );
}

function FloatingParticles() {
  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden", pointerEvents: "none", zIndex: 0 }}>
      {Array.from({ length: 20 }).map((_, i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            width: 2 + Math.random() * 3,
            height: 2 + Math.random() * 3,
            background: `rgba(201, 168, 76, ${0.15 + Math.random() * 0.3})`,
            borderRadius: "50%",
            left: `${Math.random() * 100}%`,
            top: `${Math.random() * 100}%`,
            animation: `floatParticle ${6 + Math.random() * 8}s ease-in-out infinite`,
            animationDelay: `${Math.random() * 5}s`,
          }}
        />
      ))}
    </div>
  );
}

